/* ZAnim -- the engine's sequence interpreter: CZAnimMain (the one instance, ZAnim) runs the
 * command lists of the CZAnims in each CZAnimSet. Layouts are SOCOM 1's DWARF (generated by
 * tools/dwarf1.py header, then trimmed); CZAnimMain is 0x1C4 bytes in both builds. Methods are
 * declared as the code calls them. The header's name is ours. */
#ifndef ZANIM_H
#define ZANIM_H

#include "../zmath/zmath.h"
#include "../znode/znode.h"

using zdb::CNode;

class CZAnim;
class CZAnimEx;
class CZAnimHealth;
class CZAnimSet;
class ZAnimNetworkPacket;
class _zanim_call_anim_ref;
class _zanim_cmd_hdr;
class _zanim_cmd_set;
class _zanim_node_ref;
class _zanim_particle;
class _zanim_sound;
class _zanim_tex_ref;
class _zanim_valve_ref;

/* An anim's arguments: values a caller passes when it starts the anim. */
class CZAnimArg {
public:
    enum TYPE {
        TYPE_PNT3D = 5          /* our name: the only value read so far (a point, zAnimRangeTestTick) */
    };
};

class CZAnimArgList {
public:
    CPnt3D *GetPnt3D(CZAnimArg::TYPE type);

    unsigned char _list[0x10];  /* an MSL std::list (SOCOM 1's DWARF: 0x10 bytes) */
};

class _zanim_anim_params {
public:
    unsigned char m_name_index;   // 0x0
    unsigned char m_root_node_index;   // 0x1
    unsigned char m_paused;   // 0x2
    unsigned char m_state;   // 0x3
    unsigned int m_activation : 2;   // 0x4
    unsigned int m_network_anim : 1;   // 0x4
    unsigned int node_search_scope : 2;   // 0x4
    unsigned int m_auto_copy_anim : 1;   // 0x4
    unsigned int m_auto_add_to_world : 1;   // 0x4
    unsigned int m_create_instance : 1;   // 0x4
    unsigned int m_copy_instance : 1;   // 0x4
    unsigned int m_clone_anim : 1;   // 0x4
    unsigned int m_create_root : 1;   // 0x4
    unsigned int m_max_anim_copies : 6;   // 0x4
    unsigned int m_unused_a : 2;   // 0x4
    unsigned int m_nest_error : 1;   // 0x4: SOCOM II's, set when an IF nests below 0 or past 255
    unsigned int m_unused : 12;   // 0x4
    float m_timer;   // 0x8
    float m_priority;   // 0xc
    unsigned int m_damage_seq_offset : 16;   // 0x10
    unsigned int m_activation_seq_offset : 16;   // 0x10
    unsigned int m_execution_seq_offset : 16;   // 0x14
    unsigned int m_cleanup_seq_offset : 16;   // 0x14
};   // 0x18 bytes

namespace zar {
class CZAR {
public:
    virtual ~CZAR();
    int Fetch(const char *name, void *buf, int size);
};
}

/* the engine's allocator: free and strdup with a file and line (both 0 here), the pool-backed
 * forms of SOCOM 1's _free__FPvPCci and _strdup__FPCcPCci -- not named until proven */
extern "C" void func_00180280(void *p, const char *file, int line);

class CZAnimNameIndexTable {
public:
    const char *GetName(CZAnimSet *set, int index);
    int Load(zar::CZAR &zar);
    void Unload()
    {
        if (m_index)
            func_00180280(m_index, 0, 0);
        m_index = 0;
        m_count = 0;
    }

    unsigned short* m_index;   // 0x0
    int m_count;   // 0x4
};   // 0x8 bytes

/* a ZAR the interpreter opened (zar::CZAR is polymorphic: the vtable pointer is at 0) */
class CZAnimZAR : public zar::CZAR {
public:
    virtual ~CZAnimZAR();
};

/* an object's motion script: SOCOM II's has 4 bytes more than SOCOM 1's before the counts */
class _zanim_si_script {
public:
    unsigned short script_pathname_index;   // 0x0
    unsigned short script_object_name_index;   // 0x2
    unsigned int spline_interp : 1;   // 0x4
    int _socom2_8;   // 0x8
    int total_frame_count;   // 0xc
    int script_data_size;   // 0x10
    char* script_data;   // 0x14
};

class CZAnim : public _zanim_anim_params {
public:
    const char *GetName(int index);
    _zanim_call_anim_ref *GetCallAnimRef(int index);
    _zanim_call_anim_ref *GetCallAnimRef(int index, int local);
    bool Running();
    float GetHealth();
    CNode *GetNode(int index, bool create);
    CPnt3D *GetArgPnt3D()
    {
        return m_arg_list ? m_arg_list->GetPnt3D(CZAnimArg::TYPE_PNT3D) : 0;
    }

    CZAnimArgList* m_arg_list;   // 0x18
    CZAnimNameIndexTable m_nameindex_table;   // 0x1c
    CZAnimEx* m_animEx;   // 0x24
    CZAnimHealth* m_health;   // 0x28
    unsigned char _socom2_2c[8];   // 0x2c: SOCOM II's 8 new bytes before the flags (what they hold is not known)
    unsigned int m_invalid : 1;   // 0x34 (SOCOM 1: 0x2c; every offset below moved by 8)
    unsigned int m_added_to_world_internally : 1;   // 0x2c
    unsigned int m_debug : 1;   // 0x2c
    unsigned int m_socom2_3 : 5;   // SOCOM II's: GetAnimIndex reads the set index as the byte at 0x35
    unsigned int m_animset_index : 8;   // 0x2c
    unsigned int m_node_ref_count : 8;   // 0x2c
    unsigned int m_tex_ref_count : 8;   // 0x2c
    unsigned int m_particle_count : 8;   // 0x30
    unsigned int m_sound_ref_count : 8;   // 0x30
    unsigned int m_valve_ref_count : 8;   // 0x30
    unsigned int m_call_anim_ref_count : 8;   // 0x30
    CNode* m_instance_node;   // 0x34
    _zanim_node_ref* m_node_ref_list;   // 0x38
    _zanim_tex_ref* m_tex_ref_list;   // 0x3c
    _zanim_valve_ref* m_valve_ref_list;   // 0x40
    _zanim_particle* m_particle_list;   // 0x44
    _zanim_sound* m_sound_ref_list;   // 0x48
    _zanim_call_anim_ref* m_call_anim_ref_list;   // 0x4c
    _zanim_cmd_hdr** m_user_cmd;   // 0x50
    char* m_seq_data;   // 0x54
    int m_seq_data_size;   // 0x58
    CZAnim* m_sibling_anim;   // 0x5c
};   // 0x60 bytes

class _zanim_main_params {
public:
    int m_version;   // 0x0
    float m_gravity;   // 0x4
    unsigned int m_search_external_nodes : 1;   // 0x8
    unsigned int m_unused : 31;   // 0x8
    int m_UserActionAnimIndex;   // 0xc
};   // 0x10 bytes

class CZAnimNameTable {
public:
    const char *GetName(int index);
    void Unload();

    char** m_name;   // 0x0
    int m_count;   // 0x4
};   // 0x8 bytes

/* a set of anims (one ZAR's): SOCOM II's is 0x34 bytes, SOCOM 1's 0x30 */
class CZAnimSet {
public:
    CZAnim *Anim(int index);
    int GetAnimIndex(CZAnim *anim);

    unsigned char _0[0x34];
};

enum LOD {LOW = 0, MEDIUM = 1, HIGH = 2};   // 1 byte(s)

class _zanim_cmd_hdr {
public:
    unsigned int data_type : 16;   // 0x0
    unsigned int quad_align : 1;   // 0x0
    unsigned int timeless : 1;   // 0x0
    unsigned int data_size : 14;   // 0x0
};   // 0x4 bytes

class _zsequence {
public:
    unsigned int name_index : 16;   // 0x0
    int loop_counter : 16;   // 0x0
    unsigned int paused : 1;   // 0x4
    unsigned int activation : 7;   // 0x4
    unsigned int state : 8;   // 0x4
    unsigned int cmd_state : 8;   // 0x4
    unsigned int m_IF_NestLevel : 8;   // 0x4
    char* cmd_pc;   // 0x8
    int seq_data_size;   // 0xc
    float seq_timer;   // 0x10
    float cmd_timer;   // 0x14
    float loop_timer;   // 0x18
};   // 0x1c bytes

class CZAnimMain : public _zanim_main_params {
public:
    void StopSequence(const char *name);
    void ActivateSequence(const char *name);
    void CmdSet(int index);
    void CmdNext(int bytes);
    void SeqSetState(int state);
    void CmdNext();
    bool CmdValid();
    CZAnim *GetAnim(int set, int anim);
    int StateRunning(int state);
    bool SeqRunning();
    int CloseZAR(CZAnimZAR *zar);
    int UnloadSIScript(_zanim_si_script *script);
    ZAnimNetworkPacket *GetNetworkPacket(int size);
    void FreeNetworkPacketBuffer();
    void Close();
    void Unload();
    CZAnimSet *GetAnimSet(int index);
    bool GetAnimIndex(CZAnim *anim, int *set, int *index);

    /* the command the current sequence is on */
    _zanim_cmd_hdr *CmdHdr() { return m_CurSeq ? (_zanim_cmd_hdr *)m_CurSeq->cmd_pc : 0; }

    unsigned char m_IsOpen;   // 0x10
    unsigned char m_IsStarted;   // 0x11
    unsigned char m_socom2_12;   // 0x12: SOCOM II's, in SOCOM 1's hole (Close clears both)
    unsigned char m_socom2_13;   // 0x13
    CZAnimNameTable m_name_table;   // 0x14
    CZAnimSet* m_animset_list;   // 0x1c
    int m_animset_count;   // 0x20
    int m_cmdset_count;   // 0x24
    int m_cmdset_index;   // 0x28
    int m_cmdlist_index;   // 0x2c
    _zanim_cmd_set* m_cmdset_list;   // 0x30
    CZAnimSet* m_CurAnimSet;   // 0x34
    CZAnim* m_CurAnim;   // 0x38
    _zsequence* m_CurSeq;   // 0x3c
    unsigned char m_anim_complete;   // 0x40
    unsigned char m_debug;   // 0x41
    unsigned char _pad42[0x2];   // 0x42: a hole
    CZAnim* m_UserActionAnim;   // 0x44
    LOD m_Lod;   // 0x48
    void * m_network_activation_callback;   // 0x4c
    unsigned char m_block_activation_callback;   // 0x50
    _zanim_cmd_hdr m_cmd_if;   // 0x54
    _zanim_cmd_hdr m_cmd_elseif;   // 0x58
    _zanim_cmd_hdr m_cmd_else;   // 0x5c
    _zanim_cmd_hdr m_cmd_endif;   // 0x60
    _zanim_cmd_hdr m_cmd_endwhile;   // 0x64
    _zanim_cmd_hdr m_cmd_ExprOperator;   // 0x68
    float m_exp[41];   // 0x6c
    float m_inv_exp[41];   // 0x110
    ZAnimNetworkPacket* m_NetworkPacket;   // 0x1b4
    int m_NetworkPacketMaxSize;   // 0x1b8
    int m_RunningAnimCount;   // 0x1bc
    int m_CurrentFrame;   // 0x1c0
};   // 0x1c4 bytes

class _zanim_call_anim_ref {
public:
    unsigned char name_index;   // 0x0
    unsigned char local_name_index;   // 0x1
    unsigned char stop_on_exit : 1;   // 0x2
    CZAnim* base_anim;   // 0x4
    CZAnim* executing_anim;   // 0x8
};   // 0xc bytes


/* An expression after a command (if, while): evaluated by the interpreter's own parser. */
class CZAnimExpression {
public:
    static bool ProcExpr(float *dT);
};

extern CZAnimMain ZAnim;

/* CZAnim::Resume and Pause, which SOCOM II gave a second parameter (passed 0 here, never
 * narrowed: not a bool) -- their mangled names wait on its type */
extern "C" void func_002709B0(CZAnim *anim, int arg);
extern "C" void func_00270BE0(CZAnim *anim, int arg);

/* CZAnim::Stop, which SOCOM II gave a flag (SOCOM 1: Stop__6CZAnimFv) */
extern "C" void func_002707C0(CZAnim *anim, bool now);

/* SOCOM II's own: steps a FOR_CHILDREN loop to the next child of its node */
extern "C" void func_0025E3F0(_zanim_cmd_hdr *cmd, CZAnim *anim);

/* SOCOM II's own CZAnimMain method (SOCOM 1's if/while had no nesting): moves the current
 * sequence's if-nesting level by `delta`, flags the anim when it leaves 0..255, returns it */
extern "C" int func_002681C0(CZAnimMain *main, int delta);

/* CNode::Rendered, which SOCOM II gave a parameter (2 here) */
extern "C" bool func_00315580(CNode *node, int how);

extern "C" int rand(void);

#endif
